from lib import *
S = SS('g103')
steps = [
    step("同一个字符串 \"hello\",三个不同的进程里的哈希值。maphash.String(seed1, \"hello\"):进程 1 是 0ae496e7eaa7f835,进程 2 是 46fa68a0a0c0d61e,进程 3 是 6df89d1f6f5ae8ad——每个进程都不同;同一个进程里再算一次相同;同一进程里换一个种子(seed2)得到另一个值;maphash.Hash 分两段写入 \"he\" + \"llo\" 与一次性计算相同;maphash.Comparable 对 key{1,\"x\"} 在同一进程内稳定、不同的值得到不同的哈希,跨进程不同。对照 FNV-1a 64 位 \"hello\":三个进程里都是 a430d84680aabd0b。", t=tl(S(1)), mark=lidx(S(1), 'maphash.String(seed1', 'maphash.Comparable(seed1, key{1', 'seed2'), done=lidx(S(1), '同一个进程里再算一次', '分两段写入', 'FNV-1a 64'), kv=KV([['maphash', '每个进程种子随机,跨进程不稳定'], ['同一进程', '同一种子、同一输入 → 同一哈希'], ['分段写入', '与一次性计算相同'], ['FNV-1a', '固定算法,跨进程稳定']], ['maphash'])),
    step("分布(16 万个键 \"key0\"..\"key159999\" 落进 16 个桶,理想值每桶 10000):maphash 每个桶最少 9900、最多 10132;FNV-1a 每个桶最少 9948、最多 10052。两者都很均匀。", t=tl(S(2)), mark=lidx(S(2), 'maphash 每个桶'), b=bars([['maphash:最少桶', 9900, '9900'], ['maphash:最多桶', 10132, '10132'], ['FNV-1a:最少桶', 9948, '9948'], ['FNV-1a:最多桶', 10052, '10052']], 10200, done=[0, 1, 2, 3]), kv=KV([['maphash', '9900–10132'], ['FNV-1a', '9948–10052'], ['理想值', '10000']], ['理想值'])),
    step("速度:16 字节输入:maphash.String 4 ns(4000 MB/s),FNV-1a 64 7 ns(2286 MB/s),CRC32-C 4 ns(4000 MB/s);1024 字节输入:maphash.String 77 ns(13299 MB/s),FNV-1a 64 1176 ns(871 MB/s),CRC32-C 104 ns(9846 MB/s)。输入变长时,逐字节处理的 FNV 慢得多。", t=tl(S(3)), mark=lidx(S(3), '1024 字节'), done=lidx(S(3), '16 字节'), b=bars([['1 KiB:maphash (ns)', 77, '77'], ['1 KiB:CRC32-C', 104, '104'], ['1 KiB:FNV-1a', 1176, '1176']], 1176, done=[0, 1], mark=[2]), kv=KV([['16 字节', '三者都在 4–7 ns'], ['1 KiB', 'maphash 77 ns,FNV-1a 1176 ns(约 15 倍)']], ['1 KiB'])),
    step("内置 map:两个键完全相同的 map,遍历的起点也不同。8 个键的小 map 里,顺序是一个环形轮转:[6 7 0 1 2 3 4 5] 对 [1 2 3 4 5 6 7 0];下一个进程是 [2 3 4 5 6 7 0 1] 对 [0 1 2 3 4 5 6 7]。", t=tl(S(4)), mark=lidx(S(4), '遍历顺序'), kv=KV([['相同的键', '两个 map 的遍历起点不同'], ['小 map', '顺序是环形轮转(这个例子)']], ['相同的键'])),
    step("文档(go doc hash/maphash):该包提供对字节序列和可比较值的哈希函数,还定义了 Hasher(哈希函数和哈希表之间的接口);这些哈希函数用来实现哈希表、布隆过滤器和其它需要把任意字符串或字节序列映射到 64 位无符号整数均匀分布的数据结构;每个不同的哈希表或数据结构实例应该使用自己的 Seed;这些哈希函数不是密码学安全的(密码学用途见 crypto/sha256 和 crypto/sha512)。", t=tl(S(5)), done=lidx(S(5), 'Package maphash provides'), kv=KV([['用途', '哈希表、布隆过滤器等'], ['Seed', '每个数据结构实例用自己的'], ['安全性', '不是密码学安全的']], ['Seed'])),
]
A = mkartg('g103', 103, 'Go,hash/maphash,哈希,随机种子,哈希表,真实验证,动画演示',
    '在 Go 1.27.1 里实测 hash/maphash:同一个字符串在三个进程里的哈希值各不相同(种子随进程随机),同一进程内稳定,分段写入与一次性计算相同,Comparable 可以哈希结构体;16 万个键分到 16 个桶几乎均匀;1 KiB 输入上 maphash 77 ns,FNV-1a 1176 ns;内置 map 的遍历起点也因 map 而异。',
    '哈希表要防的是“有人故意构造一批碰撞的键把它拖垮”,办法就是让哈希函数带一个随机种子,攻击者事先算不出来。hash/maphash 把 Go 内置 map 用的这种做法开放成了公共包。这篇看它的种子怎么随进程变化、分布够不够均匀、速度怎么样。',
    [('每个进程不同', '同一个字符串 "hello" 的 maphash 值在三个进程里互不相同;FNV-1a 永远是 a430d84680aabd0b'), ('77 vs 1176 ns', '哈希 1 KiB 输入:maphash.String 与 FNV-1a 64'), ('9900–10132', '16 万个键落进 16 个桶时,maphash 每个桶的数量范围(理想 10000)')],
    [('种子随进程变化', '<p><code>maphash.MakeSeed()</code> 每次都生成新的随机种子,同一个字符串在三个进程里的哈希值完全不同;同一进程内同一个种子、同一输入则稳定。FNV-1a 这类固定算法在任何进程里都是 <code>a430d84680aabd0b</code>,所以攻击者可以离线算出一批碰撞的键。因此 <code>maphash</code> 的值不能持久化、不能跨进程比较。</p>'),
     ('分布和速度', '<p>16 万个连续编号的键落进 16 个桶,<code>maphash</code> 每桶 9900 到 10132 个,FNV-1a 是 9948 到 10052,都很均匀。速度上 16 字节输入三者差不多(4–7 ns);1 KiB 时 <code>maphash.String</code> 77 ns,FNV-1a 1176 ns,差约 15 倍。</p>'),
     ('用法', '<p>文档建议每个哈希表或数据结构实例用自己的种子;它不是密码学安全的。<code>maphash.Comparable</code> 可以直接哈希可比较的值(本文试了一个含 int 和 string 的结构体)。</p>'),
     ('内置 map 的做法', '<p>内置 map 同样有随机化:两个键完全相同的 map,遍历的起点也不同(这里的小 map 是环形轮转)。这说明遍历顺序不能依赖,前面“map 遍历顺序”一篇已经单独讨论过。</p>'),
     ('文档', '<p>文档还定义了 <code>Hasher</code> 接口(哈希函数和哈希表之间的接口),本文没有使用。</p>')],
    steps,
    [ENV_G + '。三个进程分别运行同一个小程序取哈希值;分布实验用 "key0".."key159999" 共 16 万个键对 16 取模;速度用 testing.Benchmark;读过的文档:go doc hash/maphash 开头一段',
     '没有验证:内置 map 内部到底怎么用哈希种子(没有读 runtime 源码)、HashDoS 攻击的实际演示、maphash.Hasher 接口、对超长输入的速度、Linux 与其它架构上的结果、与 xxhash 等第三方哈希的比较'],
    'hash/maphash')
